#!/bin/bash
set -e
for d in ~/ivoo-mystery-shopper- ~/ivoo-mystery-shopper "$PWD"; do
  if [ -f "$d/package.json" ] && [ -d "$d/.git" ] && [ -f "$d/src/App.tsx" ]; then REPO="$d"; break; fi
done
if [ -z "$REPO" ]; then echo "No encontré la carpeta del proyecto. Ejecuta el script desde dentro de ella."; exit 1; fi
cd "$REPO"
echo "Proyecto: $REPO"
git pull -q || true

printf "061120e10f06ad27bf6073189f756f199d63f2ff5c1022274ab7b3dfed4fad9d  index.html\n5d540ed9f429112aea5e8eb5b12199f9a498a32871ce5b981c62cf79f7be082d  src/App.tsx\n42070e0b45bb201b2b838a52aaaa6e965f964e0b542d97f1fe517fe59c4b75a8  src/index.css\nf61b45b856a5bd3932ac4b0d960272795015ab65e60c3a83140b7b320492fd0a  src/components/ResumenComparativoView.tsx\nb9a6569be81cbf11ddc601e2f80ede23c2892351491d01ef382020c183fba36a  src/components/PrintReportView.tsx\n" > /tmp/ivoo_before.sha
if ! sha256sum -c --quiet /tmp/ivoo_before.sha 2>/dev/null; then
  echo "AVISO: tus archivos no están en la versión esperada. No se hizo ningún cambio."
  sha256sum -c /tmp/ivoo_before.sha 2>&1 | grep -v ": OK" || true
  exit 1
fi

base64 -d > /tmp/ivoo_theme.tgz << 'B64EOF'

B64EOF

if [ "$(sha256sum /tmp/ivoo_theme.tgz | cut -d' ' -f1)" != "3ac95a8efe82616b3ce401cc83648c356f084c4261169baf0d365af9c9f14850" ]; then echo "❌ Paquete dañado. No se hizo ningún cambio."; exit 1; fi
tar xzf /tmp/ivoo_theme.tgz
# elimina el archivo que quedó por error en la raíz del repo (si existe)
if [ -f PrintReportView.tsx ]; then git rm -q PrintReportView.tsx; fi

printf "54a7483b794aa67a82fae97ebb995c8086ba853898598996424b349af1fb8d9d  index.html\n37094438b3a3e9576951c5d91551e86e187566e6938a7d11fc4c028629954b0e  src/App.tsx\n12c991bc1c81c9389a5affc2cdfd16bcf96763a0c10ba7678d744de9bd70889d  src/index.css\n6f327b8fbc2b4802256a31d030f81cd72af189c04093f2421e71e0df037b5d31  src/components/ResumenComparativoView.tsx\n3e8fe41a5d96e5247f00a17f33bc8946e669ef618eb85ff14041ecda853c7685  src/components/PrintReportView.tsx\n" > /tmp/ivoo_after.sha
if sha256sum -c --quiet /tmp/ivoo_after.sha; then
  echo "✅ Rediseño aplicado y verificado (5 archivos)."
  echo "Ahora ejecuta:"
  echo "  git add -A && git commit -m 'Rediseño oscuro estilo gaming; fix ventana de impresion; informe sin texto fijo' && git push"
else
  echo "❌ Verificación falló. No hagas commit; avísame."; exit 1
fi
